// Pixel load event listener
pmw.bus.on("pmw:load-pixels", () => {
	if (pmwDataLayer?.pixels?.openai?.pixel_id && !pmwDataLayer?.pixels?.openai?.loaded) {
		if (pmw.consent.canPixelBeFired("marketing", "OpenAI")) pmw.loadOpenAIPixel();
	}
});

// page_viewed event (Server-to-Server)
pmw.bus.on("pmw:pixel:page-view", (payload) => {

	try {
		if (pmw.canNotFireOpenAIEvent()) return;
		if (!pmw.shouldFireBrowserPixel(payload, "openai")) return;

		const openaiData = payload.pixels?.openai;
		if (!openaiData) return;

		oaiq("measure", openaiData.event_name, openaiData.event_data, { event_id: openaiData.event_id });
		pmw.console.log("OpenAI Pixel: page_viewed event sent", openaiData.event_data);

	} catch (e) {
		console.error(e);
	}
});

