/**
 * Relay marketing consent changes to the SDK.
 *
 * The pixel is only loaded once marketing consent is granted, but a visitor
 * can withdraw it later in the cookie banner. oaiq("consent", false) stops
 * the SDK from sending measurement pings (blocked events are not replayed);
 * loadOpenAIPixel() resets a remembered denial when consent is granted again.
 * https://developers.openai.com/ads/measurement-pixel
 */
document.addEventListener("pmw:consent:update", ({ detail }) => {

	try {
		if (!pmwDataLayer?.pixels?.openai?.loaded) return;

		const granted = !!detail?.marketing;

		oaiq("consent", granted);
		pmw.console.log("OpenAI Pixel: consent updated: " + (granted ? "granted" : "denied"));

	} catch (e) {
		console.error(e);
	}
}, true);

